score = 82
if score >= 90:
    grade = "A"
elif score >= 80:
    grade = "B"
else:
    grade = "C"
print(grade)

age, has_ticket = 20, True
if age >= 19 and has_ticket:
    print("입장 가능")
else:
    print("입장 불가")

student = {"name": "Mina", "score": 95}
student["passed"] = student["score"] >= 60
for key, value in student.items():
    print(key, value)

students = [{"name": "A", "scores": [80, 90]}, {"name": "B", "scores": [70, 75]}]
for student in students:
    print(student["name"], sum(student["scores"]) / len(student["scores"]))

scores = {"Mina": [90, 85, 95], "Jin": [70, 80, 75]}
result = {name: round(sum(values) / len(values), 1) for name, values in scores.items()}
print(result)

def greet(name):
    return f"안녕하세요, {name}!"
print(greet("HAMS"))

def rectangle(width, height):
    return width * height, 2 * (width + height)
area, perimeter = rectangle(4, 3)
print(area, perimeter)

def connect(host="localhost", port=8080, secure=False):
    return f"{'https' if secure else 'http'}://{host}:{port}"
print(connect(port=3000, secure=True))

def average(*numbers):
    return sum(numbers) / len(numbers)
def profile(**fields):
    return ", ".join(f"{k}={v}" for k, v in fields.items())
print(average(1, 2, 3), profile(name="Mina", level=3))

def factorial(number):
    if number <= 1:
        return 1
    return number * factorial(number - 1)
print(factorial(5))

def total(values: list[int]) -> int:
    return sum(values)
result: int = total([1, 2, 3])
print(result)

def chunk(values, size):
    return [values[i:i + size] for i in range(0, len(values), size)]
print(chunk(list(range(1, 8)), 3))

try:
    number = int("12a")
except ValueError as error:
    print(f"숫자 변환 실패: {error}")
else:
    print(number)
finally:
    print("처리 완료")

def countdown(start):
    while start > 0:
        yield start
        start -= 1
print(list(countdown(5)))

from functools import wraps
def trace(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        print(f"call: {function.__name__}")
        return function(*args, **kwargs)
    return wrapper
@trace
def add(a, b): return a + b
print(add(2, 3))

from contextlib import contextmanager
@contextmanager
def managed_resource():
    print("open")
    try:
        yield "resource"
    finally:
        print("close")
with managed_resource() as resource:
    print(resource)

